  def impedanceDelivery_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var impedanceDelivery: EIT_Acquisition_Coordinator.ImpedanceDelivery.Type = $

  def put_impedanceDelivery(value : EIT_Acquisition_Coordinator.ImpedanceDelivery.Type) : Unit = {
    Contract(
      Modifies(impedanceDelivery),
      Ensures(
        impedanceDelivery == value
      )
    )
    Spec {
      impedanceDelivery = value
    }

    Art.putValue(impedanceDelivery_Id, EIT_Acquisition_Coordinator.ImpedanceDelivery_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

